import {pipeSegmentSummary} from './application-models.js';
import {esc} from './model.js';
import {macroMaterials} from './macro-state.js';
const field=(key,label,value,unit='')=>`<label class="field"><span>${label}</span><div class="unit-input"><input data-param="${key}" type="number" step="any" value="${esc(value??'')}">${unit?`<small>${unit}</small>`:''}</div></label>`;
const select=(key,label,value,options)=>`<label class="field"><span>${label}</span><select data-param="${key}">${options.map(([id,name])=>`<option value="${id}" ${value===id?'selected':''}>${name}</option>`).join('')}</select></label>`;
const renderGroup=(title,content,open=true)=>`<details class="algorithm-field-group" ${open?'open':''}><summary>${title}</summary><div>${content}</div></details>`;
export function extrusionFields(n,sections){const p=n.params;const group=(title,content,open=true)=>!sections||sections.includes(title)?renderGroup(title,content,open):'';
 const kinds=[['massFlow','质量流量','inletMassFlow','g/s'],['velocity','速度','inletVelocity','m/s'],['pressure','压力','inletPressure','MPa']];
 const inputs=kinds.map(([type,label,key,unit])=>`<div data-inlet-kind="${type}" ${p.inletType!==type?'hidden':''}>${field(key,'入口'+label,p[key],unit)}</div>`).join('');
 const outlets=[['pressure','压力出口','outletPressure','MPa'],['massFlow','质量流量出口','outletMassFlow','g/s']].map(([type,label,key,unit])=>`<div data-outlet-kind="${type}" ${p.outletType!==type?'hidden':''}>${field(key,label==='压力出口'?'出口压力':'出口质量流量',p[key],unit)}</div>`).join('');
 const geometry=p.modeling.primitives.filter(x=>x.pipeSegment).sort((a,b)=>a.order-b.order).map(part=>`<button type="button" class="pipe-segment-editor" data-editor="edit-geometry" data-id="${part.id}"><strong>${esc(part.name)}</strong><span>${esc(pipeSegmentSummary(part))}</span></button>`).join('');
 return group('四段几何尺寸',geometry,false)+group('整体材料物性',field('density','密度',p.density,'kg/m³')+field('viscosity','黏度',p.viscosity,'Pa·s')+field('conductivity','热导率',p.conductivity,'W/(m·K)')+field('specificHeat','比热',p.specificHeat,'J/(kg·K)')+'<p class="algorithm-note">初始值为原型演示参数，可按实际材料修改；不改写材料库。</p>')+group('边界条件','<p class="algorithm-note">质量流量、速度、压力仅选择一种输入。</p>'+select('inletType','入口输入',p.inletType,kinds.map(([id,label])=>[id,label]))+inputs+select('outletType','出口类型',p.outletType,[['pressure','压力出口（默认）'],['massFlow','质量流量出口']])+outlets+'<p class="algorithm-note">出口默认压力出口，一般无需更改。压力按表压输入。</p>');
}
export function timFields(n,sections){const p=n.params;const group=(title,content,open=true)=>!sections||sections.includes(title)?renderGroup(title,content,open):'';
 const presets=macroMaterials(n).filter(m=>m.region==='filler').map(m=>`<label class="field"><span>${esc(m.name)} · 颗粒预设</span><select data-tim-preset="${esc(m.id)}"><option value="sphere" ${m.shape!=='platelet'?'selected':''}>球状颗粒 · 固定预设</option><option value="platelet" ${m.shape==='platelet'?'selected':''}>片状颗粒 · 固定预设</option></select></label>`).join('');
 return group('几何与颗粒',field('length','长方体长度',p.length,'mm')+field('width','长方体宽度',p.width,'mm')+field('height','长方体高度',p.height,'mm')+(sections?'':presets)+'<p class="algorithm-note">颗粒形貌在材料管理中设置。单颗粒形状与尺寸随预设固定，不开放自定义尺寸；具体预设尺寸待算法配置。柱体颗粒轴向暂不设置。</p>'+`<fieldset class="algorithm-distribution"><legend>颗粒位置分布</legend>${['均一','随机'].map(value=>`<label><input type="radio" name="tim-distribution" data-param="distribution" value="${value}" ${p.distribution===value?'checked':''}>${value}分布</label>`).join('')}</fieldset>`+field('seed','随机种子',p.seed)+field('gap','颗粒最小间隙',p.gap,'mm')+'<p class="algorithm-note">任意两填充颗粒之间应至少保留上述间隙，预览为分布示意，真实间隙由几何生成与检验确定。</p>')+group('热物性输入',field('matrix','基体热导率',p.matrix,'W/(m·K)')+field('filler','填料热导率',p.filler,'W/(m·K)')+field('resistance','基体–填料界面热阻',p.resistance,'m²·K/W'))+group('温度边界',select('direction','计算导热方向',p.direction,[['X','X 方向'],['Y','Y 方向'],['Z','Z 方向']])+field('hot','热端温度',p.hot,'°C')+field('cold','冷端温度',p.cold,'°C')+'<label class="field"><span>侧面边界条件</span><input value="绝热（固定）" readonly></label>');
}
